/* Compiles the UNCHANGED native timer/accessor function bodies generated by
   run_tests.py. This checks data/timing semantics, not success in a battle. */
#include <stdio.h>
#include <string.h>
#include "ude_db.h"
#include "native_functions.h"

static int fails,checks;
static void verify(int good) { checks++;if(!good)fails++; }

int main(int argc,char **argv) {
    FILE *f;
    int ch,id,i,k,ability,last=-100,auto_presses=0,wasted=0;
    unsigned char expected[21];
    BtlAtkRecord record;
    BtlTechChr chr;
    BtlMoveChr m;
    UdeDbSnapshot s;
    UdeDbState state;
    UdeDbConfig cfg;
    UdeDbDecision d;
    UrIncoming contacts[2], merged;
    if(argc!=2 || !(f=fopen(argv[1],"rb")))return 2;
    memset(&record,0,sizeof record);chr.record=&record;
    for(ch=0;ch<161;ch++)for(id=0;id<163;id++) {
        const UdeDbAttack *a=UdeDb_Attack(ch,id);
        unsigned flags;
        if(fread(expected,1,sizeof expected,f)!=sizeof expected)return 3;
        flags=(unsigned)expected[0]|((unsigned)expected[1]<<8)|((unsigned)expected[2]<<16)|((unsigned)expected[3]<<24);
        verify(a->flags==flags && a->priority==(signed char)expected[4]);
        for(i=0;i<4;i++)verify(a->guard[i]==(signed char)expected[5+i]);
        record.flags=a->flags;record.priority=a->priority;
        record.guardA=a->guard[0];record.guardB=a->guard[1];record.guardC=a->guard[2];record.guardE=a->guard[3];
        chr.id=id;
        verify(BtlAtk_GetFlags(&chr)==flags && BtlAtk_GetPriority(&chr)==(signed char)expected[4]);
        for(ability=0;ability<2;ability++) {
            int result[6];
            chr.ability40=ability;
            result[0]=BtlAtk_GetGuardKindA(&chr);result[1]=BtlAtk_GetGuardKindB(&chr);result[2]=BtlAtk_GetGuardKindC(&chr);
            result[3]=BtlAtk_GetBestGuardKind(&chr);result[4]=BtlAtk_GetGuardKindE(&chr);result[5]=0;
            for(i=0;i<6;i++)verify(result[i]==(signed char)expected[9+ability*6+i]);
        }
    }
    verify(fgetc(f)==EOF);fclose(f);
    memset(&m,0,sizeof m);m.health=1.0f;m.unkFB0=1;m.flags[5]=1;m.caps=0x20;
    m.unk1068=m.unk106C=m.unk1070=m.unk1078=m.unk107C=-30;m.unk1074=-15;
    m.held=1;BtlMove_UpdateDefenseTimers(&m);
    verify(m.unk1068==4 && m.unk106C==2 && m.unk1078==5 && m.unk107C==2);
    m.previous=0;BtlMove_UpdateDefenseTimers(&m);
    verify(m.unk1068==-1 && m.unk106C==-1 && m.unk1078==4 && m.unk107C==-1);
    m.held=0x41;m.previous=0;m.unk1074=-15;BtlMove_UpdateDefenseTimers(&m);verify(m.unk1074==5);
    m.previous=0;BtlMove_UpdateDefenseTimers(&m);verify(m.unk1074==4);
    m.flags[5]=0;m.held=0x18;m.previous=0;m.unk1070=-30;BtlMove_UpdateDefenseTimers(&m);verify(m.unk1070==1);
    m.flags[0x80]=1;m.ability38=1;m.held=0;m.previous=0;BtlMove_UpdateDefenseTimers(&m);verify(m.unk106C==1);
    memset(contacts,0,sizeof contacts);contacts[0].eta=0.2f;contacts[0].evadable=1;contacts[0].db1PriorHits=0;
    contacts[1].eta=0.6f;contacts[1].evadable=1;contacts[1].db1PriorHits=3;
    merged=ur_merge(contacts,2);verify(merged.db1PriorHits==3);
    contacts[1].eta=0.8f;merged=ur_merge(contacts,2);verify(merged.db1PriorHits==0);
    memset(&s,0,sizeof s);memset(&m,0,sizeof m);UdeDb_DefaultConfig(&cfg);cfg.enabled=1;UdeDb_Reset(&state);
    s.battle.valid=s.battle.have_ext=s.battle.have_recipe=s.battle.fighting=s.battle.game_free=1;
    s.battle.my_action=0xB;s.battle.opp_action=0x70;s.battle.opp_attacking=1;s.battle.close=1;
    s.battle.flag5=1;s.battle.anim_flags=0xB1;s.battle.my_ki=100000;
    s.battle.recipe[UDE_X_OK]=1;s.battle.recipe[UDE_X_MELEE]=1;s.battle.recipe[UDE_X_FIRST_HIT]=1;
    s.battle.recipe[UDE_X_DODGE_WIN]=1;s.battle.recipe[UDE_X_OPP_UNK2]=2;
    for(id=11;id<163;id++)if((UdeDb_Attack(0,id)->flags&1)&&!(UdeDb_Attack(0,id)->flags&0x4000000))break;
    s.battle.opp_attack_id=id;s.battle.opp_attack_flags=(int)UdeDb_Attack(0,id)->flags;
    m.health=1.0f;m.unkFB0=1;m.flags[5]=1;
    m.unk1068=m.unk106C=m.unk1070=m.unk1078=m.unk107C=-30;m.unk1074=-15;
    for(i=0;i<3000;i++) {
        int *wins=&m.unk1068;
        for(k=0;k<6;k++)s.battle.win[k]=wins[k];
        UdeDb_Step(&state,&cfg,&s,0,(unsigned)i,&d);
        m.previous=m.held;m.held=d.buttons;
        if(d.press_edge){verify(i-last>=30);last=i;auto_presses++;}
        BtlMove_UpdateDefenseTimers(&m);
        if(d.press_edge && (m.unk1068==-1||m.unk106C==-1||m.unk107C==-1))wasted++;
    }
    verify(auto_presses>50 && wasted==0 && state.manual_overwrites==0);
    printf("native_records=26243 native_checks=%d temporal_updates=3000 auto_presses=%d wasted_taps=%d failed=%d\n",checks,auto_presses,wasted,fails);
    return fails?1:0;
}
